This Terraform configuration creates an AWS DynamoDB table with encryption at rest enabled using DynamoDB server-side encryption. The table uses on-demand billing and defines a simple primary key named `id`.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the DynamoDB table will be created."
  type        = string
  default     = "us-east-1"
}

variable "table_name" {
  description = "Name of the DynamoDB table."
  type        = string
  default     = "encrypted-dynamodb-table"
}

resource "aws_dynamodb_table" "encrypted_table" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"

  hash_key = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  tags = {
    Name        = var.table_name
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

output "dynamodb_table_name" {
  description = "Name of the encrypted DynamoDB table."
  value       = aws_dynamodb_table.encrypted_table.name
}

